/* functracer.c — captures function enter/exit events generated by -finstrument-functions
 * Usage: LD_PRELOAD=./functracer.so FUNC_TRACE_OUT=/tmp/trace.log ./program args...
 * Output format: each line "> function_name" (enter) or "< function_name" (exit)
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <dlfcn.h>
#include <string.h>
#include <stdlib.h>

static FILE *trace_out = NULL;
static int enabled = 0;
static unsigned long last_base = 0;
__thread int in_hook = 0;   /* prevent hook recursion */

static void write_event(const char *dir, void *func, void *caller)
{
    if (!enabled || in_hook) return;
    in_hook = 1;
    Dl_info info;
    if (dladdr(func, &info) && info.dli_fbase) {
        unsigned long off = (unsigned long)func - (unsigned long)info.dli_fbase;
        if (info.dli_sname)
            fprintf(trace_out, "%s %s\n", dir, info.dli_sname);
        else {
            /* local symbol (e.g. static function): record module path + offset,
             * resolve with nm afterwards.  Emit the mapping line only when the
             * module changes: large C++ binaries otherwise emit one mapping
             * line per call, bloating the trace to tens of GB. */
            if ((unsigned long)info.dli_fbase != last_base) {
                fprintf(trace_out, "M %p %s\n", info.dli_fbase,
                        info.dli_fname ? info.dli_fname : "?");
                last_base = (unsigned long)info.dli_fbase;
            }
            fprintf(trace_out, "%s @%lx\n", dir, off);
        }
    }
    in_hook = 0;
}

void __cyg_profile_func_enter(void *func, void *caller) __attribute__((no_instrument_function));
void __cyg_profile_func_exit(void *func, void *caller) __attribute__((no_instrument_function));

void __cyg_profile_func_enter(void *func, void *caller) {
    write_event(">", func, caller);
}
void __cyg_profile_func_exit(void *func, void *caller) {
    write_event("<", func, caller);
}

__attribute__((constructor))
static void init(void) {
    const char *path = getenv("FUNC_TRACE_OUT");
    if (!path) return;
    trace_out = fopen(path, "w");
    if (trace_out) {
        setvbuf(trace_out, NULL, _IOLBF, 0);
        enabled = 1;
    }
}

__attribute__((destructor))
static void fini(void) {
    if (trace_out) fclose(trace_out);
}
